#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[101];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int pos, x;
    scanf("%d %d", &pos, &x);
    memmove(a + pos + 1, a + pos, (size_t)(n - pos) * sizeof a[0]);
    a[pos] = x;
    n++;
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", a[i]);
    }
    return 0;
}

