#include <stdio.h>

void *my_memmove(void *dst, const void *src, size_t n) {
    unsigned char *d = dst;
    const unsigned char *s = src;
    if (d < s) {
        for (size_t i = 0; i < n; i++) {
            d[i] = s[i];
        }
    } else if (d > s) {
        for (size_t i = n; i > 0; i--) {
            d[i - 1] = s[i - 1];
        }
    }
    return dst;
}

int main(void) {
    char s[64];
    int q;
    scanf("%63s %d", s, &q);
    for (int i = 0; i < q; i++) {
        int dst, src, len;
        scanf("%d %d %d", &dst, &src, &len);
        my_memmove(s + dst, s + src, (size_t)len);
        printf("%s\n", s);
    }
    return 0;
}

